class Solution { private String replace(String text,char from,char to){return text.replace(from,to);}public int maxDiff(int num){String text=String.valueOf(num),maximum=text,minimum=text;for(char value:text.toCharArray())if(value!='9'){maximum=replace(text,value,'9');break;}if(text.charAt(0)!='1')minimum=replace(text,text.charAt(0),'1');else for(int i=1;i<text.length();i++)if(text.charAt(i)!='0'&&text.charAt(i)!='1'){minimum=replace(text,text.charAt(i),'0');break;}return Integer.parseInt(maximum)-Integer.parseInt(minimum);} }
